export const hasBundledPluginFallback = (pluginId: string): boolean => {
  return pluginId in FALLBACK_PLUGINS;
};

export const installBundledPluginFallback = async (
  pluginId: string,
): Promise<string> => {
  const plugin = FALLBACK_PLUGINS[pluginId];
  if (!plugin) {
    throw new Error(`No bundled fallback available for ${pluginId}`);
  }

  Logger.plugins.info(`Using bundled fallback files for ${pluginId}`);
  const targetRelDir = `plugins/.downloads/${pluginId}`;
  const subFolder = plugin.isTs ? 'src' : 'dist';
  const targetRelCodeDir = `plugins/.downloads/${pluginId}/${subFolder}`;

  await ensureDir(targetRelDir);
  await mkdir(targetRelCodeDir, {
    recursive: true,
    baseDir: BaseDirectory.AppData,
  });

  await writeTextFile(
    `${targetRelDir}/package.json`,
    JSON.stringify(plugin.manifest, null, 2),
    { baseDir: BaseDirectory.AppData },
  );

  const codeFile = plugin.isTs ? 'index.ts' : 'index.js';
  await writeTextFile(
    `${targetRelCodeDir}/${codeFile}`,
    plugin.code,
    { baseDir: BaseDirectory.AppData },
  );

  const base = await appDataDir();
  return join(base, targetRelDir);
};
